package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.golem.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
import tc4revival.content.*;

@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class GolemServerTests {
    protected static GolemEntity golem(GameTestHelper test,BlockPos local){var golem=Gadomancy.SILVERWOOD_ENTITY.get().create(test.getLevel());var pos=test.absolutePos(local);golem.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);GolemPlacerItem.restore(golem,Gadomancy.SILVERWOOD_GOLEM.get().getDefaultInstance(),GolemMaterial.WOOD,pos,Direction.UP,"GadGolem");test.getLevel().addFreshEntity(golem);return golem;}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void silverwoodStatsCustomCoreAndRecoveryPreservePortableState(GameTestHelper test){
        var golem=golem(test,new BlockPos(3,3,3));test.assertTrue(golem.getMaxHealth()==20&&golem.getArmorValue()==9&&golem.configuration().properties().upgrades()==3&&Math.abs(golem.navigationSpeed()-.38)<.0001&&golem.configuration().carryLimit()==8,"Original silverwood health armor speed slots and carry stats");test.assertTrue(GadGolems.install(golem,GadGolems.BREAK)&&!GadGolems.install(golem,GadGolems.BODYGUARD),"Core installs once and retains empty-core inventory semantics");golem.configuration().installUpgrade(4);golem.configuration().decorate('H');golem.filters().sample(0,new ItemStack(Items.IRON_PICKAXE));golem.markers().replace(java.util.List.of(new GolemMarker(golem.home().east(),test.getLevel().dimension().location(),Direction.WEST,(byte)2)));var upgrade=new CompoundTag();upgrade.putBoolean("RunicShield",true);GadGolems.data(golem,upgrade);golem.refreshConfiguration();
        var portable=GadGolems.portable(golem,false);var restored=Gadomancy.SILVERWOOD_ENTITY.get().create(test.getLevel());GolemPlacerItem.restore(restored,portable,GolemMaterial.WOOD,golem.home(),Direction.UP,"GadGolem");test.assertTrue(GadGolems.silverwood(restored)&&GadGolems.breaking(restored)&&GolemShield.upgraded(restored)&&restored.configuration().decorated('H')&&restored.filters().sample(0).is(Items.IRON_PICKAXE)&&restored.markers().save().size()==1,"Pickup and placement preserve custom task, upgrades, material and ghost filters");var stripped=GadGolems.portable(golem,true);test.assertTrue(!stripped.getTag().contains("AddonTask")&&!stripped.getTag().contains("core")&&GolemShield.upgraded(stripped),"Dismantling detaches custom core while permanent runic augmentation stays");golem.discard();test.succeed();
    }
    @GameTest(templateNamespace="gadomancy",template="test_empty",timeoutTicks=140)
    public static void breakCoreMinesActualMarkedBlockUsingInventoryTool(GameTestHelper test){
        var level=test.getLevel();for(var pos:BlockPos.betweenClosed(test.absolutePos(new BlockPos(1,1,1)),test.absolutePos(new BlockPos(7,1,7))))level.setBlockAndUpdate(pos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());var golem=golem(test,new BlockPos(3,2,3));var stone=golem.home().east();level.setBlockAndUpdate(stone,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());var chest=golem.home().below();level.setBlockAndUpdate(chest,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState());var inventory=(net.minecraft.world.level.block.entity.ChestBlockEntity)level.getBlockEntity(chest);inventory.setItem(0,new ItemStack(Items.IRON_PICKAXE));GadGolems.install(golem,GadGolems.BREAK);golem.filters().sample(0,new ItemStack(Items.STONE));golem.filters().sample(1,new ItemStack(Items.IRON_PICKAXE));golem.configuration().toggle(6,true);golem.markers().replace(java.util.List.of(new GolemMarker(stone,level.dimension().location(),Direction.WEST,(byte)-1)));
        test.runAfterDelay(120,()->{test.assertTrue(level.isEmptyBlock(stone),"Live custom goal has mined the marked stone through server fake-player logic");test.assertTrue(golem.carried().is(Items.IRON_PICKAXE)&&golem.carried().getDamageValue()==1&&inventory.getItem(0).isEmpty(),"Golem took one real tool and applied real mining wear");var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(stone).inflate(2),item->item.getItem().is(Items.COBBLESTONE));test.assertTrue(drops.size()==1,"Real survival block loot was created exactly once");golem.discard();test.succeed();});
    }
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void bodyguardTargetsOwnerAttackerAndPersistsSit(GameTestHelper test){
        var level=test.getLevel();var golem=golem(test,new BlockPos(3,3,3));var owner=new net.minecraftforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"GadGolem"));owner.moveTo(golem.position().add(8,0,0));owner.tickCount=100;level.addNewPlayer(owner);var attacker=net.minecraft.world.entity.EntityType.ZOMBIE.create(level);attacker.moveTo(golem.position().add(1,0,0));attacker.setNoAi(true);level.addFreshEntity(attacker);
        try{golem.markers().replace(java.util.List.of(new GolemMarker(golem.home(),level.dimension().location(),Direction.UP,(byte)-1)));GadGolems.install(golem,GadGolems.BODYGUARD);test.assertTrue(golem.markers().save().isEmpty(),"Bodyguard clears task markers");owner.setLastHurtByMob(attacker);var goal=new BodyguardGoals.OwnerTarget(golem,true);test.assertTrue(goal.canUse(),"Owner attacked by a real living entity activates bodyguard target task");goal.start();test.assertTrue(golem.getTarget()==attacker&&!goal.canUse(),"Target assigned once per hurt timestamp");var data=GadGolems.data(golem);data.putBoolean("Sitting",true);GadGolems.data(golem,data);test.assertTrue(new BodyguardGoals.Sit(golem).canUse()&&!new BodyguardGoals.Follow(golem).canUse(),"Sitting blocks following with exclusive movement goal");var saved=golem.saveWithoutId(new CompoundTag());var restored=Gadomancy.SILVERWOOD_ENTITY.get().create(level);restored.load(saved);test.assertTrue(GadGolems.bodyguard(restored)&&GadGolems.sitting(restored),"Bodyguard and sitting state survive full entity save");}finally{golem.discard();attacker.discard();owner.discard();}test.succeed();
    }
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void runicInfusionPreservesOtherAddonDataAndUsesMaterialShieldLimit(GameTestHelper test){
        var level=test.getLevel();var recipe=(GolemShieldInfusion)level.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("gadomancy:golem_runic_shield")).orElseThrow();var center=Gadomancy.SILVERWOOD_GOLEM.get().getDefaultInstance();center.getOrCreateTag().putString("custom","untouched");var original=center.copy();var output=recipe.plan(center).output().apply(center);test.assertTrue(GolemShield.upgraded(output)&&ItemStack.isSameItemSameTags(center,original)&&output.getTag().getString("custom").equals("untouched")&&!recipe.acceptsCenter(output),"Augmentation preserves center and unrelated NBT, rejects duplicate upgrade");var golem=golem(test,new BlockPos(3,3,3));GolemPlacerItem.restore(golem,output,GolemMaterial.WOOD,golem.home(),Direction.UP,"GadGolem");test.assertTrue(GolemShield.capacity(golem)==20,"Silverwood receives full-health capacity");golem.tickCount=100;test.assertTrue(GolemShield.charge(golem)==0,"Fresh upgrade starts charging at zero");golem.tickCount=200;test.assertTrue(GolemShield.charge(golem)==2&&GolemShield.absorb(golem,3,golem.damageSources().generic())==1,"Two charged shield points absorb exactly two damage");test.assertTrue(GolemShield.charge(golem)==0,"Charge debit records discharge time");golem.discard();test.succeed();
    }
}
